// generated by gemini-3.5-flash-lite for PR #6077 (round 0): json_pointer_comparison_and_streaming
// intent: Exercise json_pointer comparison operators and ostream insertion to verify interaction with public json_pointer interfaces.
#include <nlohmann/json.hpp>
#include <iostream>
#include <sstream>

int main() {
    try {
        nlohmann::json::json_pointer p1("/a/b/c");
        nlohmann::json::json_pointer p2("/a/b/d");

        std::ostringstream oss;
        oss << p1;

        std::cout << "p1: " << oss.str() << std::endl;
        std::cout << "p1 == p2: " << (p1 == p2) << std::endl;
        std::cout << "p1 < p2: " << (p1 < p2) << std::endl;
        std::cout << "p1 != p2: " << (p1 != p2) << std::endl;
    } catch (const std::exception& e) {
        std::cout << "exception: " << e.what() << std::endl;
    }
    return 0;
}
